def traducir() -> list[str]:
    """Escribe web/src/en/*.md. Devuelve los textos que no se encontraron (vacío si todo va bien)."""
    EN.mkdir(parents=True, exist_ok=True)
    faltan = []
    for pagina, pares in PAGINAS.items():
        s = (SRC / pagina).read_text(encoding="utf-8")
        for es, en in [*RUTAS, *COMUN, *pares]:
            if es not in s:
                if (es, en) in COMUN or (es, en) in RUTAS:  # opcionales: no todas las páginas los tienen
                    continue
                faltan.append(f"{pagina}: {es[:80]!r}")
                continue
            s = s.replace(es, en)
        # índice de la página en inglés
        if "toc: false" not in s:
            s = s.replace("\n---\n", '\ntoc:\n  label: "On this page"\n---\n', 1)
        # aviso tras la cabecera (la cabecera YAML tiene que ir lo primero)
        cab, cuerpo = s.split("\n---\n", 1)
        aviso = f"<!-- GENERADO por `rma traducir` a partir de ../{pagina}: no editar a mano -->"
        (EN / pagina).write_text(f"{cab}\n---\n{aviso}\n{cuerpo}", encoding="utf-8")
    return faltan
